PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://example.org/ref#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?ts ?point ?pclass ?zone ?label WHERE {
  ?point owl:sameAs|brick:hasSubclass|a ?pclass .
  ?zone a brick:Zone ; rdfs:label "Perimeter_ZN_2" .
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point rdfs:label ?label }
  FILTER (CONTAINS(LCASE(STR(?pclass)), "temperature") || CONTAINS(LCASE(STR(?pclass)), "setpoint"))
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://example.org/ref#>
SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER (CONTAINS(LCASE(STR(?o)), "Perimeter_ZN_2") || CONTAINS(LCASE(STR(?s)), "Perimeter_ZN_2"))
} LIMIT 50

